import timeimport threadingimport jsonimport sysimport tracebackimport tkinter as tkfrom tkinter import filedialog, messagebox, scrolledtextfrom dataclasses import dataclassfrom pathlib import Pathimport psutilimport carlafrom gui.CarlaControl import start_carla, kill_carla_processesfrom helpers.carla_monitor import CarlaMonitorCONFIG_PATH = Path.home() / ".carla_gui_full_config.json"def load_saved_config():    """Return a dict with keys: carla_executable, recording_extension, input_path, output_path."""    if CONFIG_PATH.exists():        try:            return json.loads(CONFIG_PATH.read_text())        except Exception:            return {}    return {}def save_config_to_disk(cfg: "ConfigData"):    """Persist all four fields."""    CONFIG_PATH.write_text(json.dumps({        "carla_executable": cfg.carla_executable,        "recording_extension": cfg.recording_extension,        "input_path": cfg.input_path,        "output_path": cfg.output_path    }))@dataclassclass ConfigData:    carla_executable: str    recording_extension: str    input_path: str    output_path: strclass TextRedirector:    def __init__(self, log_fn):        self.log_fn = log_fn    def write(self, text):        if text.strip():            for line in text.rstrip().splitlines():                self.log_fn(line)    def flush(self):        passclass CarlaConfigApp:    def __init__(self, root):        self.root = root        root.title("CARLA Configuration")        root.geometry("800x600")        # Make grid resizable...        for col in range(4):            root.columnconfigure(col, weight=1)        for row in range(7):            root.rowconfigure(row, weight=1 if row == 6 else 0)        # Load saved or defaults        saved = load_saved_config()        self.exe_var = tk.StringVar(value=saved.get("carla_executable", ""))        self.ext_var = tk.StringVar(value=saved.get("recording_extension", ""))        self.input_var = tk.StringVar(value=saved.get("input_path", ""))        self.output_var = tk.StringVar(value=saved.get("output_path", ""))        # GUI elements        tk.Label(root, text="CARLA Executable Path") \            .grid(row=0, column=0, sticky='w', padx=5, pady=5)        tk.Entry(root, textvariable=self.exe_var) \            .grid(row=0, column=1, columnspan=2, sticky='ew', padx=5)        tk.Button(root, text="Browse", command=self.browse_executable) \            .grid(row=0, column=3, padx=5)        tk.Label(root, text="Recording File Extension") \            .grid(row=1, column=0, sticky='w', padx=5, pady=5)        tk.Entry(root, textvariable=self.ext_var, width=10) \            .grid(row=1, column=1, sticky='w', padx=5)        tk.Label(root, text="Input File or Folder") \            .grid(row=2, column=0, sticky='w', padx=5, pady=5)        tk.Entry(root, textvariable=self.input_var) \            .grid(row=2, column=1, sticky='ew', padx=5)        tk.Button(root, text="Browse File", command=self.browse_input_file).grid(row=2, column=2, padx=2)        tk.Button(root, text="Browse Folder", command=self.browse_input_folder).grid(row=2, column=3, padx=2)        tk.Label(root, text="Output Destination Path") \            .grid(row=3, column=0, sticky='w', padx=5, pady=5)        tk.Entry(root, textvariable=self.output_var) \            .grid(row=3, column=1, columnspan=2, sticky='ew', padx=5)        tk.Button(root, text="Browse", command=self.browse_output).grid(row=3, column=3, padx=5)        self.submit_btn = tk.Button(root, text="Submit", command=self.on_submit)        self.submit_btn.grid(row=4, column=1, columnspan=1, pady=10, sticky='ew')        self.stop_btn = tk.Button(root, text="Stop", command=self.on_stop, state='disabled')        self.stop_btn.grid(row=4, column=2, columnspan=1, pady=10, sticky='ew')        tk.Label(root, text="Elapsed time:").grid(row=5, column=0, sticky='e')        self.timer_label = tk.Label(root, text="00:00")        self.timer_label.grid(row=5, column=1, sticky='w')        self.log_text = scrolledtext.ScrolledText(root, state='disabled')        self.log_text.grid(row=6, column=0, columnspan=4, sticky='nsew', padx=5, pady=5)        self._start_time = None        self._timer_job = None        # Cancellation event        self.cancel_event = threading.Event()        self._timer_job = None        self._start_time = None    # --- Browse methods (unchanged) ---    def browse_executable(self):        path = filedialog.askopenfilename(            title="Select CARLA Executable",            filetypes=[("Windows Executable", "*.exe"), ("Shell Script", "*.sh")],        )        if path: self.exe_var.set(path)    def browse_input_file(self):        ext = self.ext_var.get().lstrip(".")        if not ext:            messagebox.showwarning("No Extension", "Please enter a recording file extension first.")            return        path = filedialog.askopenfilename(            title="Select a CARLA recording file",            filetypes=[("Recording files", f"*.{ext}")],        )        if path: self.input_var.set(path)    def browse_input_folder(self):        folder = filedialog.askdirectory(title="Select folder of recordings")        if folder: self.input_var.set(folder)    def browse_output(self):        folder = filedialog.askdirectory(title="Select output destination")        if folder: self.output_var.set(folder)    # --- Logging & Timer (unchanged) ---    def log(self, msg: str):        def append():            self.log_text.configure(state='normal')            self.log_text.insert(tk.END, msg + "\n")            self.log_text.see(tk.END)            self.log_text.configure(state='disabled')        self.root.after(0, append)    def start_timer(self):        self._start_time = time.time()        self._update_timer()    def _update_timer(self):        elapsed = int(time.time() - self._start_time)        mins, secs = divmod(elapsed, 60)        self.timer_label.config(text=f"{mins:02d}:{secs:02d}")        self._timer_job = self.root.after(500, self._update_timer)    def stop_timer(self):        if self._timer_job:            self.root.after_cancel(self._timer_job)            self._timer_job = None    def on_submit(self):        # Clear any previous cancel request        self.cancel_event.clear()        # Disable Submit so you can’t start again mid‐run        self.submit_btn.config(state='disabled')        # **Enable** Stop so you can cancel the run        self.stop_btn.config(state='normal')        self.log_text.configure(state='normal')        self.log_text.delete('1.0', tk.END)        self.log_text.configure(state='disabled')        cfg = ConfigData(            carla_executable=self.exe_var.get().strip(),            recording_extension=(self.ext_var.get().strip()                                 if self.ext_var.get().strip().startswith('.')                                 else f".{self.ext_var.get().strip()}"),            input_path=self.input_var.get().strip(),            output_path=self.output_var.get().strip(),        )        if not all([cfg.carla_executable, cfg.recording_extension,                    cfg.input_path, cfg.output_path]):            messagebox.showerror("Missing Fields", "All fields must be filled.")            self.submit_btn.config(state='normal')            return        # Persist all four settings now:        save_config_to_disk(cfg)        worker = threading.Thread(target=self.run_workflow, args=(cfg,), daemon=True)        worker.start()        self.start_timer()    def run_monitor(self, cfg: ConfigData):        client = self.client        monitor = CarlaMonitor(carla_client=client)        monitor.monitor_simulation_run(            file_path=cfg.input_path,            weather_file_path="",            result_file_path=cfg.output_path        )    def run_workflow(self, cfg: ConfigData):        old_out, old_err = sys.stdout, sys.stderr        sys.stdout = sys.stderr = TextRedirector(self.log)        try:            steps = [                ("Killing existing CARLA", lambda: kill_carla_processes()),                ("Waiting 2s", lambda: time.sleep(2)),                (f"Starting CARLA: {cfg.carla_executable}", lambda: start_carla(cfg.carla_executable)),                ("Waiting 20s for CARLA", lambda: time.sleep(20)),                ("Connecting to CARLA", self.connect_to_carla),                (f"Running monitor on {cfg.input_path}", lambda: self.run_monitor(cfg)),                ("Waiting 10s before shutdown", lambda: time.sleep(10)),            ]            for desc, action in steps:                if self.cancel_event.is_set():                    self.log(f">> Cancelled before: {desc}")                    return                self.log(f">> {desc}…")                action()        except Exception:            traceback.print_exc()        finally:            self.log(">> Cleaning up CARLA processes")            kill_carla_processes()            self.log(">> All done")            sys.stdout, sys.stderr = old_out, old_err            # UI reset            self.root.after(0, lambda: self.submit_btn.config(state='normal'))            self.root.after(0, lambda: self.stop_btn.config(state='disabled'))            self.stop_timer()    def connect_to_carla(self):        client = carla.Client('localhost', 2000)        client.set_timeout(60.0)        client.get_world().get_actors()        self.client = client    def on_stop(self):        # signal cancel, kill CARLA, and log        self.cancel_event.set()        kill_carla_processes()        self.log(">> Stop requested — terminating run.")        # disable and enable buttons        self.stop_btn.config(state='disabled')        self.submit_btn.config(state='normal')if __name__ == "__main__":    root = tk.Tk()    app = CarlaConfigApp(root)    root.mainloop()